function start_doc(obj::wxDCBase, msg::AbstractString)
    msg_ws = wxString(msg)
    _result = try
        KwxFFI.wxDC_StartDoc(obj.ptr, msg_ws.ptr) != 0
    finally
        Base.delete!(msg_ws)
    end
    return _result
end

function start_page!(obj::wxDCBase)
